import { useState } from 'react';

export default function {{component_name}}({ colors }: { colors: string[] }) {
  const [picked, setPicked] = useState(colors[0]);
  return (
    <div className="flex gap-2">
      {colors.map((c) => (
        <button
          key={c}
          onClick={() => setPicked(c)}
          style={{ background: c }}
          className={`w-8 h-8 rounded-full border-2 ${picked === c ? 'border-black' : 'border-transparent'}`}
        />
      ))}
    </div>
  );
}
